description:
Implement a `useOnline` hook that returns `true` when the browser is online and `false` when offline. It should initialise from `navigator.onLine` and update when `online` / `offline` events fire on `window`.

**Example:**
```tsx
const isOnline = useOnline();
return isOnline ? <App /> : <OfflineBanner />;
```

starter_code:
import { useEffect, useState } from 'react';

export function useOnline(): boolean {
  // your code here
}

test_suite:
test('returns a boolean', () => {
  const { result } = renderHook(() => useOnline());
  expect(typeof result.current).toBe('boolean');
});

test('returns true when navigator.onLine is true', () => {
  Object.defineProperty(navigator, 'onLine', { writable: true, configurable: true, value: true });
  const { result } = renderHook(() => useOnline());
  expect(result.current).toBe(true);
});

test('updates to false on offline event', () => {
  Object.defineProperty(navigator, 'onLine', { writable: true, configurable: true, value: true });
  const { result } = renderHook(() => useOnline());
  act(() => {
    Object.defineProperty(navigator, 'onLine', { writable: true, configurable: true, value: false });
    window.dispatchEvent(new Event('offline'));
  });
  expect(result.current).toBe(false);
});

test('updates to true on online event', () => {
  Object.defineProperty(navigator, 'onLine', { writable: true, configurable: true, value: false });
  const { result } = renderHook(() => useOnline());
  act(() => {
    Object.defineProperty(navigator, 'onLine', { writable: true, configurable: true, value: true });
    window.dispatchEvent(new Event('online'));
  });
  expect(result.current).toBe(true);
});

// __hidden__
test('removes event listeners on unmount', () => {
  const spy = vi.spyOn(window, 'removeEventListener');
  const { unmount } = renderHook(() => useOnline());
  unmount();
  const calls = spy.mock.calls.map(c => c[0]);
  expect(calls).toContain('online');
  expect(calls).toContain('offline');
  spy.mockRestore();
});

solution:
import { useEffect, useState } from 'react';

export function useOnline(): boolean {
  const [online, setOnline] = useState(navigator.onLine);

  useEffect(() => {
    const goOnline = () => setOnline(true);
    const goOffline = () => setOnline(false);
    window.addEventListener('online', goOnline);
    window.addEventListener('offline', goOffline);
    return () => {
      window.removeEventListener('online', goOnline);
      window.removeEventListener('offline', goOffline);
    };
  }, []);

  return online;
}
